package keystrokesmod.script.packet.serverbound;
import net.minecraft.entity.player.PlayerCapabilities; import net.minecraft.network.play.client.C13PacketPlayerAbilities;
public class C13 extends CPacket { public boolean invulnerable,flying,allowFlying,creativeMode; public float flySpeed,walkSpeed; public C13(boolean inv,boolean fly,boolean allow,boolean creative,float flySpeed,float walkSpeed){super(create(inv,fly,allow,creative,flySpeed,walkSpeed));invulnerable=inv;flying=fly;allowFlying=allow;creativeMode=creative;this.flySpeed=flySpeed;this.walkSpeed=walkSpeed;} public C13(C13PacketPlayerAbilities value){super(value);} private static C13PacketPlayerAbilities create(boolean inv,boolean fly,boolean allow,boolean creative,float speed,float walk){PlayerCapabilities caps=new PlayerCapabilities();caps.disableDamage=inv;caps.isFlying=fly;caps.allowFlying=allow;caps.isCreativeMode=creative;caps.setFlySpeed(speed);return new C13PacketPlayerAbilities(caps);} public C13PacketPlayerAbilities convert(){return (C13PacketPlayerAbilities)packet;} }
